#include "VulkanRectPipeline.h"

// SPIR-V bytecode generated by glslc — see CMakeLists.txt (VulkanShaders target).
#include <rect_frag_spv.h>
#include <rect_vert_spv.h>

#include <BECore/Logger/LogEvent.h>
#include <BECore/Math/Color.h>
#include <CoreVulkan/VulkanPipelineState.h>

namespace BECore {

    bool VulkanRectPipeline::Initialize(VkDevice device, VkRenderPass renderPass, bool linearizeColors) {
        VkPushConstantRange pushRange{};
        pushRange.stageFlags = VK_SHADER_STAGE_VERTEX_BIT | VK_SHADER_STAGE_FRAGMENT_BIT;
        pushRange.offset = 0;
        pushRange.size = sizeof(PushConstants);

        VkPipelineLayoutCreateInfo layoutInfo{};
        layoutInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
        layoutInfo.pushConstantRangeCount = 1;
        layoutInfo.pPushConstantRanges = &pushRange;

        if (vkCreatePipelineLayout(device, &layoutInfo, nullptr, &_pipelineLayout) != VK_SUCCESS) {
            LOG_ERROR("VulkanRectPipeline: failed to create pipeline layout");
            return false;
        }

        // The colour space of the target: kLinearize (constant 0) of the shader that takes the colour
        const VkBool32 linearizeValue = linearizeColors ? VK_TRUE : VK_FALSE;
        const VkSpecializationMapEntry linearizeEntry{0, 0, sizeof(VkBool32)};
        const VkSpecializationInfo linearizeInfo{1, &linearizeEntry, sizeof(VkBool32), &linearizeValue};

        // No vertex input — geometry is generated in the vertex shader.
        VkPipelineVertexInputStateCreateInfo vertexInput{};
        vertexInput.sType = VK_STRUCTURE_TYPE_PIPELINE_VERTEX_INPUT_STATE_CREATE_INFO;

        _pipeline = CreatePipeline2D(device, renderPass, _pipelineLayout, {kRectVertSpv, kRectVertSpvSize}, {kRectFragSpv, kRectFragSpvSize, &linearizeInfo}, vertexInput);
        if (_pipeline == VK_NULL_HANDLE) {
            LOG_ERROR("VulkanRectPipeline: failed to create graphics pipeline");
            return false;
        }

        return true;
    }

    void VulkanRectPipeline::Destroy(VkDevice device) {
        if (_pipeline != VK_NULL_HANDLE) {
            vkDestroyPipeline(device, _pipeline, nullptr);
            _pipeline = VK_NULL_HANDLE;
        }
        if (_pipelineLayout != VK_NULL_HANDLE) {
            vkDestroyPipelineLayout(device, _pipelineLayout, nullptr);
            _pipelineLayout = VK_NULL_HANDLE;
        }
    }

    void VulkanRectPipeline::Draw(VkCommandBuffer cmd, float x, float y, float w, float h,
                                  const Color& color, VkExtent2D extent, const VkRect2D& scissor) const {
        PushConstants pc{};
        pc.rectX = x;
        pc.rectY = y;
        pc.rectW = w;
        pc.rectH = h;
        pc.colorR = color.r / 255.0f;
        pc.colorG = color.g / 255.0f;
        pc.colorB = color.b / 255.0f;
        pc.colorA = color.a / 255.0f;
        pc.screenW = static_cast<float>(extent.width);
        pc.screenH = static_cast<float>(extent.height);

        vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_GRAPHICS, _pipeline);

        VkViewport viewport{};
        viewport.width = pc.screenW;
        viewport.height = pc.screenH;
        viewport.minDepth = 0.0f;
        viewport.maxDepth = 1.0f;
        vkCmdSetViewport(cmd, 0, 1, &viewport);

        vkCmdSetScissor(cmd, 0, 1, &scissor);

        vkCmdPushConstants(cmd, _pipelineLayout,
                           VK_SHADER_STAGE_VERTEX_BIT | VK_SHADER_STAGE_FRAGMENT_BIT,
                           0, sizeof(PushConstants), &pc);

        vkCmdDraw(cmd, 6, 1, 0, 0);
    }

}  // namespace BECore
